(function(){
  'use strict';
  const M=window.MixtureGuideModel,P=window.MixtureGuidePlanner,$=id=>document.getElementById(id),KEY='miscela-guide-v1';
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=(n,d=3)=>Number(n).toLocaleString('it-IT',{maximumFractionDigits:d,useGrouping:'always'});
  const amount=p=>fmt(p.quantity)+' '+p.unit;
  const defaults={fieldName:'Il mio campo',area:'5',capacity:'1000',technical:'5',recipeId:'herbicide'};
  let data={version:1,settings:{...defaults},job:null,history:[]},storageOK=true;
  try{
    const raw=window.localStorage.getItem(KEY);
    if(raw){const saved=JSON.parse(raw);if(saved.version!==1||!saved.settings||!Array.isArray(saved.history))throw new Error('Formato non valido');
      if(saved.job){const j=saved.job,recalculated=P.plan(saved.settings);if(!['planned','preparing','ready','completed'].includes(j.status)||!Number.isInteger(j.loadIndex)||j.loadIndex<0||j.loadIndex>=recalculated.loads.length||!Number.isInteger(j.stepIndex)||j.stepIndex<0||j.stepIndex>3||!Array.isArray(j.confirmations)||!Array.isArray(j.usedLoads))throw new Error('Guida non valida');
        if(j.status==='preparing'&&j.stepIndex>=3||j.status==='planned'&&(j.stepIndex!==0||j.loadIndex!==0)||['ready','completed'].includes(j.status)&&j.stepIndex!==3||j.status==='completed'&&j.loadIndex!==recalculated.loads.length-1)throw new Error('Passaggio salvato non valido');
        saved.job={...j,...recalculated};}
      data={version:1,settings:{...defaults,...saved.settings},job:saved.job||null,history:saved.history.filter(h=>h&&Number.isFinite(h.at)&&Number.isFinite(h.area)&&Number.isInteger(h.confirmedLoads)&&Number.isInteger(h.loads)).slice(-20)};
    }
  }catch{$('storageNotice').hidden=false;$('storageNotice').textContent='La guida salvata non è disponibile. Puoi iniziare una nuova preparazione.';}
  function save(){try{window.localStorage.setItem(KEY,JSON.stringify(data));}catch{storageOK=false;$('storageNotice').hidden=false;$('storageNotice').textContent='Salvataggio non disponibile su questo dispositivo. La guida resta attiva finché questa pagina è aperta.';}}
  function error(message){$('error').hidden=!message;$('error').textContent=message||'';}
  function recipe(){return M.recipeById(data.settings.recipeId)||M.recipes[0];}
  function links(r){return '<div class="links"><a href="'+esc(r.productUrl)+'" target="_blank" rel="noopener noreferrer">Scheda prodotto ↗</a><a href="'+esc(r.documentationUrl)+'" target="_blank" rel="noopener noreferrer">Documentazione ↗</a></div>';}
  function totals(plan){return '<div class="totals"><div class="total"><span>PRODOTTO PER IL CAMPO</span><strong>'+amount(plan.requirements.products[0])+'</strong><small>'+esc(recipe().product)+'</small></div><div class="total"><span>MISCELA PER IL CAMPO</span><strong>'+fmt(plan.requirements.totalMixture)+' L</strong><small>Volume finale della miscela</small></div></div>';}
  function render(){
    error('');const job=data.job,index=!job?0:job.status==='planned'?1:2;
    $('progress').innerHTML=['Campo','Carichi','Prepara'].map((label,i)=>'<li class="'+(i===index?'active':i<index?'complete':'')+'" '+(i===index?'aria-current="step"':'')+'><b>'+(i+1)+'</b>'+label+'</li>').join('');
    $('historyCount').textContent=String(data.history.length);
    if(!job)renderSetup();else if(job.status==='planned')renderPlan();else if(job.status==='preparing')renderStep();else if(job.status==='ready')renderReady();else renderDone();
  }
  function renderSetup(){
    const r=recipe();$('content').innerHTML='<p class="eyebrow">Prima del trattamento</p><h1>Prepara la miscela,<br>un passo alla volta.</h1><p class="lead">Scegli una ricetta, inserisci la superficie e segui le quantità per ogni carico.</p><form id="setupForm" class="card"><h2>Che trattamento prepari?</h2><div class="recipe-options" aria-label="Tipo di trattamento">'+M.recipes.map(x=>'<button type="button" class="recipe-option" data-recipe="'+x.id+'" aria-pressed="'+(x.id===r.id)+'">'+x.category+'</button>').join('')+'</div><div id="recipeInfo"></div><div class="form-grid"><div class="field wide"><label for="fieldName">Nome del campo</label><input id="fieldName" maxlength="80" value="'+esc(data.settings.fieldName)+'" autocomplete="off"></div><div class="field"><label for="area">Superficie (ha)</label><input id="area" inputmode="decimal" value="'+esc(data.settings.area)+'" required></div><div class="field"><label for="capacity">Serbatoio (L)</label><input id="capacity" inputmode="decimal" value="'+esc(data.settings.capacity)+'" required></div></div><details><summary>Volume tecnico della macchina</summary><div class="field"><label for="technical">Volume non erogabile (L)</label><input id="technical" inputmode="decimal" value="'+esc(data.settings.technical)+'" required><small>Valore configurabile: viene conteggiato separatamente, senza aumentare la dose destinata al campo.</small></div></details><div id="preview" style="margin-top:20px" aria-live="polite"></div><label class="check"><input id="initialCheck" type="checkbox" required><span>Confermo serbatoio vuoto e macchina pronta per questa ricetta.</span></label><button class="primary" type="submit">Calcola i carichi →</button></form>';
    for(const id of ['fieldName','area','capacity','technical'])$(id).addEventListener('input',()=>{data.settings[id]=$(id).value;save();preview();});
    document.querySelectorAll('[data-recipe]').forEach(b=>b.addEventListener('click',()=>{data.settings.recipeId=b.dataset.recipe;save();document.querySelectorAll('[data-recipe]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.recipe===data.settings.recipeId)));recipeInfo();preview();}));
    $('setupForm').addEventListener('submit',e=>{e.preventDefault();if(data.job||!$('initialCheck')?.checked)return;try{data.job=P.create(data.settings);save();render();window.scrollTo({top:0,behavior:'instant'});}catch(e){error(e.message);}});recipeInfo();preview();
  }
  function recipeInfo(){const r=recipe();$('recipeInfo').innerHTML='<div class="recipe-info"><p class="eyebrow">'+esc(r.treatmentName)+'</p><div class="product">'+esc(r.product)+'</div><div class="manufacturer">'+esc(r.manufacturer)+'</div><div class="context">'+esc(r.crop)+' · '+esc(r.target)+'</div><div class="dose">Dose configurata (demo): <b>'+fmt(r.dose)+' '+esc(r.doseUnit)+'</b></div>'+links(r)+'</div>';}
  function preview(){try{const plan=P.plan(data.settings);$('preview').innerHTML=totals(plan)+'<p class="note">'+plan.loads.length+' '+(plan.loads.length===1?'carico':'carichi')+' · '+fmt(plan.area)+' ha · '+fmt(recipe().rate)+' L/ha</p>';error('');}catch(e){$('preview').innerHTML='<p class="note">Inserisci valori validi per calcolare le quantità.</p>';}}
  function technicalNote(job){return job.machine.technical>0?'<p class="note">Il piano include anche '+fmt(job.machine.technical)+' L di volume tecnico iniziale. Preparazione complessiva: <b>'+fmt(job.totalPrepared)+' L</b>, di cui '+fmt(job.requirements.totalMixture)+' L destinati al campo. Il volume tecnico noto resta nel serbatoio tra i carichi, con la stessa ricetta.</p>':'<p class="note">Acqua: portare la miscela al volume finale indicato. Il prodotto è già incluso in questo volume.</p>';}
  function renderPlan(){const j=data.job;$('content').innerHTML='<p class="eyebrow">'+esc(j.fieldName)+' · '+fmt(j.area)+' ha</p><h1>'+j.loads.length+' '+(j.loads.length===1?'carico pronto da preparare.':'carichi, quantità già calcolate.')+'</h1><p class="lead">'+esc(recipe().product)+' · '+esc(recipe().treatmentName)+'</p><div class="card">'+totals(j)+technicalNote(j)+'<div class="loads">'+j.loads.map(l=>'<article class="load '+(l.number===1?'current':'')+'"><h3>Carico '+l.number+' <span class="badge">'+(l.number===j.loads.length?'Ultimo carico':'')+'</span></h3><strong>'+fmt(l.targetVolume)+' L</strong><p>Acqua: portare la miscela a questo volume.</p><p><b>'+amount(l.products[0])+'</b> di '+esc(l.products[0].name)+'</p><p>'+fmt(l.area)+' ha previsti'+(l.existing>0?' · '+fmt(l.existing)+' L già presenti':'')+'</p></article>').join('')+'</div><div class="actions"><button id="editPlan" class="secondary">Modifica dati</button><button id="begin" class="primary">Prepara il carico 1 →</button></div></div>';
    $('editPlan').onclick=()=>{data.job=null;save();render();};$('begin').onclick=()=>{if(P.start(j)){save();render();window.scrollTo({top:0,behavior:'instant'});}};}
  function renderStep(){
    const j=data.job,l=j.loads[j.loadIndex],step=l.steps[j.stepIndex],r=recipe();
    const names={water:'1. Prepara',product:'2. Aggiungi',final:'3. Completa'};
    const instruction=step.kind==='water'?(step.amount!==null?'Porta il volume nel serbatoio a <span class="amount">'+fmt(step.amount)+' L</span> con una prima quantità d’acqua.':'Versa una prima quantità d’acqua nel serbatoio.'):step.kind==='product'?'Aggiungi <span class="amount">'+fmt(step.amount)+' '+esc(step.unit)+'</span> di '+esc(step.name)+'.':'Porta la miscela al volume finale di <span class="amount">'+fmt(step.amount)+' L</span>.';
    const checks={water:'Ho inserito la prima quantità d’acqua.',product:'Ho aggiunto la quantità di prodotto indicata.',final:'Ho completato il volume finale della miscela.'};
    $('content').innerHTML='<p class="eyebrow">Carico '+l.number+' di '+j.loads.length+' · '+esc(j.fieldName)+'</p><h1>'+esc(r.product)+'</h1><p class="lead">'+fmt(l.targetVolume)+' L di miscela finale · '+fmt(l.area)+' ha previsti</p><div class="card"><div class="step-count" aria-label="Passo '+(j.stepIndex+1)+' di 4">'+[0,1,2,3].map(i=>'<span class="step-dot '+(i<=j.stepIndex?'done':'')+'"></span>').join('')+'</div><div class="step-title">'+names[step.kind]+'</div><p class="instruction">'+instruction+'</p>'+(step.note?'<p class="step-note">'+esc(step.note)+'</p>':'')+(l.existing>0&&step.kind==='water'?'<p class="note">Questo carico considera '+fmt(l.existing)+' L della stessa miscela già presenti. Il prodotto viene aggiunto solo per la miscela nuova.</p>':'')+'<label class="check"><input id="stepCheck" type="checkbox"><span>'+checks[step.kind]+'</span></label><button id="confirmStep" class="primary" disabled>'+ (step.kind==='final'?'Conferma · Carico pronto ✓':'Conferma e continua →')+'</button><button id="cancelGuide" class="text-button">Interrompi guida</button>'+links(r)+'</div>';
    const loadIndex=j.loadIndex,stepIndex=j.stepIndex;$('stepCheck').onchange=()=>{$('confirmStep').disabled=!$('stepCheck').checked;};
    $('confirmStep').onclick=()=>{if(data.job!==j||j.status!=='preparing'||j.loadIndex!==loadIndex||j.stepIndex!==stepIndex||!$('stepCheck')?.checked)return;if(P.confirm(j,loadIndex,stepIndex)){save();render();window.scrollTo({top:0,behavior:'instant'});}};
    $('cancelGuide').onclick=()=>{if(data.job===j&&j.status==='preparing'&&window.confirm('Interrompere la guida? Le conferme già registrate restano nello storico.')){archive('Interrotta');data.job=null;save();render();}};
  }
  function renderReady(){const j=data.job,l=j.loads[j.loadIndex],last=j.loadIndex===j.loads.length-1;$('content').innerHTML='<p class="eyebrow">Carico '+l.number+' di '+j.loads.length+'</p><h1>Miscela pronta.</h1><p class="lead">La preparazione di questo carico è completata.</p><div class="card"><div class="success-icon" aria-hidden="true">✓</div><h2>'+fmt(l.targetVolume)+' L di miscela finale</h2><ul class="ready-list"><li><span>'+esc(recipe().product)+'</span><b>'+amount(l.products[0])+' aggiunti</b></li><li><span>Superficie prevista</span><b>'+fmt(l.area)+' ha</b></li><li><span>Campo</span><b>'+esc(j.fieldName)+'</b></li></ul>'+(last?'<p class="note">È l’ultimo carico della guida. Le conferme di preparazione rimarranno nello storico.</p>':'<p class="step-note">Utilizza questo carico prima di preparare il successivo. Prosegui solo dopo averlo effettivamente utilizzato; il rabbocco mantiene la stessa ricetta.</p><label class="check"><input id="usedCheck" type="checkbox"><span>Ho utilizzato il carico. Nel serbatoio restano i '+fmt(j.machine.technical)+' L tecnici configurati.</span></label>')+'<button id="nextLoad" class="primary" '+(last?'':'disabled')+'>'+(last?'Termina guida ✓':'Prepara il prossimo carico →')+'</button></div>';
    const loadIndex=j.loadIndex;if(!last)$('usedCheck').onchange=()=>{$('nextLoad').disabled=!$('usedCheck').checked;};
    $('nextLoad').onclick=()=>{if(data.job!==j||j.status!=='ready'||j.loadIndex!==loadIndex||!last&&!$('usedCheck')?.checked)return;if(P.next(j,loadIndex)){if(j.status==='completed')archive('Preparazione completata');save();render();window.scrollTo({top:0,behavior:'instant'});}};
  }
  function archive(outcome){const j=data.job;data.history.push({id:j.id,at:Date.now(),fieldName:j.fieldName,area:j.area,recipeId:j.recipeId,outcome,confirmedLoads:j.status==='completed'?j.loads.length:j.loadIndex+(j.status==='ready'?1:0),loads:j.loads.length,totalPrepared:j.totalPrepared,confirmations:j.confirmations.map(c=>({...c}))});data.history=data.history.slice(-20);}
  function renderDone(){const j=data.job;$('content').innerHTML='<p class="eyebrow">Guida completata</p><h1>Preparazione registrata.</h1><p class="lead">Tutti i '+j.loads.length+' '+(j.loads.length===1?'carico':'carichi')+' sono stati preparati seguendo la ricetta configurata.</p><div class="card"><div class="success-icon" aria-hidden="true">✓</div><h2>'+esc(j.fieldName)+' · '+fmt(j.area)+' ha</h2>'+totals(j)+technicalNote(j)+'<p class="note">Sono state registrate '+j.confirmations.length+' conferme. La guida non misura il trattamento effettivo sul campo.</p><button id="newGuide" class="primary">Nuova preparazione →</button></div>';$('newGuide').onclick=()=>{data.job=null;save();render();};}
  $('historyButton').onclick=()=>{$('historyContent').innerHTML=data.history.length?data.history.slice().reverse().map(h=>'<article class="history-item"><h3>'+esc(h.fieldName)+'</h3><p>'+esc(new Date(h.at).toLocaleString('it-IT'))+' · '+fmt(h.area)+' ha</p><p>'+esc(M.recipeById(h.recipeId)?.product||'Ricetta non disponibile')+'</p><p>'+h.confirmedLoads+' / '+h.loads+' carichi preparati</p><span class="badge">'+esc(h.outcome)+'</span></article>').join(''):'<p class="empty">Le preparazioni completate o interrotte compariranno qui.</p>';$('historyDialog').showModal();};
  $('closeHistory').onclick=()=>{$('historyDialog').close();};$('disclaimer').textContent=M.disclaimer;render();
  if('serviceWorker' in navigator)window.addEventListener('load',()=>{navigator.serviceWorker.register('sw.js').catch(()=>{});});
})();
